class ProofBase<Input = any, Output = any> {
  static publicInputType: FlexibleProvable<any> = undefined as any;
  static publicOutputType: FlexibleProvable<any> = undefined as any;
  static tag: () => { name: string } = () => {
    throw Error(
      `You cannot use the \`Proof\` class directly. Instead, define a subclass:\n` +
        `class MyProof extends Proof<PublicInput, PublicOutput> { ... }`
    );
  };
  publicInput: Input;
  publicOutput: Output;
  proof: Pickles.Proof;
  maxProofsVerified: 0 | 1 | 2;
  shouldVerify = Bool(false);

  /**
   * To verify a recursive proof inside a ZkProgram method, it has to be "declared" as part of
   * the method. This is done by calling `declare()` on the proof.
   *
   * Note: `declare()` is a low-level method that most users will not have to call directly.
   * For proofs that are inputs to the ZkProgram, it is done automatically.
   *
   * You can think of declaring a proof as a similar step as witnessing a variable, which introduces
   * that variable to the circuit. Declaring a proof will tell Pickles to add the additional constraints
   * for recursive proof verification.
   *
   * Similar to `Provable.witness()`, `declare()` is a no-op when run outside ZkProgram compilation or proving.
   * It returns `false` in that case, and `true` if the proof was actually declared.
   */
  declare() {
    if (!ZkProgramContext.has()) return false;
    const ProofClass = this.constructor as Subclass<typeof ProofBase>;
    ZkProgramContext.declareProof({ ProofClass, proofInstance: this });
    return true;
  }

  toJSON(): JsonProof {
    let fields = this.publicFields();
    return {
      publicInput: fields.input.map(String),
      publicOutput: fields.output.map(String),
      maxProofsVerified: this.maxProofsVerified,
      proof: Pickles.proofToBase64([this.maxProofsVerified, this.proof]),
    };

class Proof<Input, Output> extends ProofBase<Input, Output> {
  /**
   * Sets the `shouldVerify` flag to `true`
   * The downstream effect of this is that the proof will be verified when the circuit is run
   *
   * @note This method is meant to be called in a circuit.  Executing it outside of a circuit will have no effect.
   */
  verify() {
    this.shouldVerify = Bool(true);
  }
  /**
   * Sets the `shouldVerify` flag to the given condition param
   * If set to `Bool(true)`, the proof will be verified when the circuit is run
   * If set to `Bool(false)`, the proof will not be verified when the circuit is run
   *
   * @note This method is meant to be called in a circuit.  Executing it outside of a circuit will have no effect.
   */
  verifyIf(condition: Bool) {
    this.shouldVerify = condition;
  }

  static async fromJSON<S extends Subclass<typeof Proof>>(
    this: S,
    {
      maxProofsVerified,
      proof: proofString,
      publicInput: publicInputJson,
      publicOutput: publicOutputJson,
    }: JsonProof
  ): Promise<Proof<InferProvable<S['publicInputType']>, InferProvable<S['publicOutputType']>>> {
    await initializeBindings();
    let [, proof] = Pickles.proofOfBase64(proofString, maxProofsVerified);
    let fields = publicInputJson.map(Field).concat(publicOutputJson.map(Field));
    return this.provable.fromFields(fields, [[], [], [proof, maxProofsVerified]]) as any;
  }

// now all proofs are declared - check that we got as many as during compile time
assert(
  proofs.length === verifiedProofs.length,
  `Expected ${verifiedProofs.length} proofs, but got ${proofs.length}`
);

// extract proof statements for Pickles
let previousStatements = proofs.map(({ proofInstance }): Pickles.Statement<FieldVar> => {
  let fields = proofInstance.publicFields();
  let input = MlFieldArray.to(fields.input);
  let output = MlFieldArray.to(fields.output);
  return MlPair(input, output);
});

// handle dynamic proofs
proofs.forEach(({ ProofClass, proofInstance }) => {
  if (!(proofInstance instanceof DynamicProof)) return;

  // Initialize side-loaded verification key
  const tag = ProofClass.tag();
  const computedTag = SideloadedTag.get(tag.name);
  const vk = proofInstance.usedVerificationKey;

  if (vk === undefined) {
    throw new Error('proof.verify() not called, call it at least once in your circuit');
  }

  if (Provable.inProver()) {
    Pickles.sideLoaded.inProver(computedTag, vk.data);
  }
  const circuitVk = Pickles.sideLoaded.vkToCircuit(() => vk.data);

  // Assert the validity of the auxiliary vk-data by comparing the witnessed and computed hash
  const hash = inCircuitVkHash(circuitVk);
  Field(hash).assertEquals(vk.hash, 'Provided VerificationKey hash not correct');
  Pickles.sideLoaded.inCircuit(computedTag, circuitVk);
});

// if the output is empty, we don't evaluate `toFields(result)` to allow the function to return something else in that case
let hasPublicOutput = publicOutputType.sizeInFields() !== 0;
let publicOutput = hasPublicOutput ? publicOutputType.toFields(result.publicOutput) : [];

if (state !== undefined && auxiliaryType !== undefined && auxiliaryType.sizeInFields() !== 0) {
  Provable.asProver(() => {
    let { auxiliaryOutput } = result;
    assert(
      auxiliaryOutput !== undefined,
      `${proofSystemTag.name}.${methodName}(): Auxiliary output is undefined even though the method declares it.`
    );
    state.setAuxiliaryOutput(Provable.toConstant(auxiliaryType, auxiliaryOutput), methodName);
  });
}

return {
  publicOutput: MlFieldArray.to(publicOutput),
  previousStatements: MlArray.to(previousStatements),
  previousProofs: MlArray.to(proofs.map((p) => p.proofInstance.proof)),
  shouldVerify: MlArray.to(
    proofs.map((proof) => proof.proofInstance.shouldVerify.toField().value)
  ),
};

/**
 * Initializes Pickles bindings, serializes the input proof and verification key for use in OCaml, then calls into the Pickles verify function and returns the result.
 *
 * @note This function is meant to be called in JavaScript, not for use in a circuit.  The verification key data and hash are not confirmed to match.
 * @param proof Either a `Proof` instance or a serialized JSON proof
 * @param verificationKey Either a base64 serialized verification key or a `VerificationKey` instance which will be base64 serialized for use in the bindings.
 * @returns A promise that resolves to a boolean indicating whether the proof is valid.
 */
async function verify(
  proof: ProofBase<any, any> | JsonProof,
  verificationKey: Base64VerificationKeyString | VerificationKey
) {
  await initializeBindings();
  let picklesProof: Pickles.Proof;
  let statement: Pickles.Statement<FieldConst>;
  if (typeof proof.proof === 'string') {
    // json proof
    [, picklesProof] = Pickles.proofOfBase64(proof.proof, proof.maxProofsVerified);
    let input = MlFieldConstArray.to((proof as JsonProof).publicInput.map(Field));
    let output = MlFieldConstArray.to((proof as JsonProof).publicOutput.map(Field));
    statement = MlPair(input, output);
  } else {
    // proof class
    picklesProof = proof.proof;
    let fields = (proof as ProofBase).publicFields();
    let input = MlFieldConstArray.to(fields.input);
    let output = MlFieldConstArray.to(fields.output);
    statement = MlPair(input, output);
  }
  let vk = typeof verificationKey === 'string' ? verificationKey : verificationKey.data;
  return prettifyStacktracePromise(
    withThreadPool(() => Pickles.verify(statement, picklesProof, vk))
  );
}

/**
 * Serializable representation of a Pickles proof, useful for caching compiled proofs.
 */
type JsonProof = {
  /** Array of string, where each string is a `Field` in the publicInput of this proof */
  publicInput: string[];
  /** Array of string, where each string is a `Field` in the publicOutput of this proof */
  publicOutput: string[];
  maxProofsVerified: 0 | 1 | 2;
  proof: Base64ProofString;

export const RecursiveProgram = ZkProgram({
  name: 'recursive-program',
  publicInput: Field,

  methods: {
    baseCase: {
      privateInputs: [],
      async method(input: Field) {
        input.assertEquals(Field(0));
      },
    },

    inductiveCase: {
      privateInputs: [SelfProof],
      async method(input: Field, earlierProof: SelfProof<Field, void>) {
        earlierProof.verify();
        earlierProof.publicInput.add(1).assertEquals(input);
      },
    },
  },
});

/**
 * Sets the `shouldVerify` flag to `true`
 * The downstream effect of this is that the proof will be verified when the circuit is run
 *
 * @param vk The verification key this proof will be verified against
 *
 * @note This method is meant to be called in a circuit.  Executing it outside of a circuit will have no effect.
 * @note The vk parameter will have its auxiliary data checked in the circuit, so the hash must match the data, or else the proof will fail
 */
verify(vk: VerificationKey) {
  this.shouldVerify = Bool(true);
  this.usedVerificationKey = vk;
}
/**
 * Sets the `shouldVerify` flag to the given condition param
 * If set to `Bool(true)`, the proof will be verified when the circuit is run
 * If set to `Bool(false)`, the proof will not be verified when the circuit is run
 *
 * @param vk The verification key this proof will be verified against
 * @param condition The condition to set the shouldVerify flag to
 *
 * @note This method is meant to be called in a circuit.  Executing it outside of a circuit will have no effect.
 * @note The vk parameter will have its auxiliary data checked in the circuit, so the hash must match the data, or else the proof will fail
 */
verifyIf(vk: VerificationKey, condition: Bool) {
  this.shouldVerify = condition;
  this.usedVerificationKey = vk;
}

// handle dynamic proofs
proofs.forEach(({ ProofClass, proofInstance }) => {
  if (!(proofInstance instanceof DynamicProof)) return;

  // Initialize side-loaded verification key
  const tag = ProofClass.tag();
  const computedTag = SideloadedTag.get(tag.name);
  const vk = proofInstance.usedVerificationKey;

  if (vk === undefined) {
    throw new Error('proof.verify() not called, call it at least once in your circuit');
  }

  if (Provable.inProver()) {
    Pickles.sideLoaded.inProver(computedTag, vk.data);
  }
  const circuitVk = Pickles.sideLoaded.vkToCircuit(() => vk.data);

  // Assert the validity of the auxiliary vk-data by comparing the witnessed and computed hash
  const hash = inCircuitVkHash(circuitVk);
  Field(hash).assertEquals(vk.hash, 'Provided VerificationKey hash not correct');
  Pickles.sideLoaded.inCircuit(computedTag, circuitVk);

static async checkValidity(key: VerificationKey): Promise<boolean> {
  try {
    let { runAndCheckSync } = await synchronousRunners();

    runAndCheckSync(() => {
      let vk = Pickles.sideLoaded.vkToCircuit(() => key.data);
      let inCircuitHash = inCircuitVkHash(vk);
      inCircuitHash.assertEquals(key.hash);
    });
    return true;
  } catch {
    return false;
  }

/**
 * Initializes Pickles bindings, serializes the input proof and verification key for use in OCaml, then calls into the Pickles verify function and returns the result.
 *
 * @note This function is meant to be called in JavaScript, not for use in a circuit.  The verification key data and hash are not confirmed to match.
 * @param proof Either a `Proof` instance or a serialized JSON proof
 * @param verificationKey Either a base64 serialized verification key or a `VerificationKey` instance which will be base64 serialized for use in the bindings.
 * @returns A promise that resolves to a boolean indicating whether the proof is valid.
 */
async function verify(
  proof: ProofBase<any, any> | JsonProof,
  verificationKey: Base64VerificationKeyString | VerificationKey
