type State<A> = {
  /**
   * Get the current on-chain state.
   *
   * Caution: If you use this method alone inside a smart contract, it does not prove that your contract uses the current on-chain state.
   * To successfully prove that your contract uses the current on-chain state, you must add an additional `.requireEquals()` statement or use `.getAndRequireEquals()`:
   *
   * ```ts
   * let x = this.x.get();
   * this.x.requireEquals(x);
   * ```
   *
   * OR
   *
   * ```ts
   * let x = this.x.getAndRequireEquals();
   * ```
   */
  get(): A;
  /**
   * Get the current on-chain state and prove it really has to equal the on-chain state,
   * by adding a precondition which the verifying Mina node will check before accepting this transaction.
   */
  getAndRequireEquals(): A;
  /**
   * Set the on-chain state to a new value.
   */
  set(a: A): void;
  /**
   * Asynchronously fetch the on-chain state. This is intended for getting the state outside a smart contract.
   */
  fetch(): Promise<A | undefined>;
  /**
   * Prove that the on-chain state has to equal the given state,
   * by adding a precondition which the verifying Mina node will check before accepting this transaction.
   */
  requireEquals(a: A): void;
  /**
   * Require that the on-chain state has to equal the given state if the provided condition is true.
   *
   * If the condition is false, this is a no-op.
   * If the condition is true, this adds a precondition that the verifying Mina node will check before accepting this transaction.
   */
  requireEqualsIf(condition: Bool, a: A): void;
  /**
   * **DANGER ZONE**: Override the error message that warns you when you use `.get()` without adding a precondition.
   */
  requireNothing(): void;

getAndRequireEquals() {
  let state = this.get();
  this.requireEquals(state);
  return state;

function assertStatePrecondition(sc: SmartContract) {
  try {
    for (let [key, context] of getStateContexts(sc)) {
      // check if every state that was read was also constrained
      if (!context?.wasRead || context.wasConstrained) continue;
      // we accessed a precondition field but not constrained it explicitly - throw an error
      let errorMessage = `You used \`this.${key}.get()\` without adding a precondition that links it to the actual on-chain state.
Consider adding this line to your code:
this.${key}.requireEquals(this.${key}.get());`;
      throw Error(errorMessage);
    }
  } finally {
    cleanStatePrecondition(sc);
  }

async settle(proof: Proof<OffchainStateCommitments, OffchainStateCommitments>) {
  // verify the proof
  proof.verify();

  // check that proof moves state forward from the one currently stored
  let state = getContract().offchainStateCommitments.getAndRequireEquals();
  Provable.assertEqual(OffchainStateCommitments, state, proof.publicInput);

  // require that proof uses the correct pending actions
  getContract().account.actionState.requireEquals(proof.publicOutput.actionState);

  // update the state
  getContract().offchainStateCommitments.set(proof.publicOutput);
},

async function compile({
  cache = Cache.FileSystemDefault,
  forceRecompile = false,
  proofsEnabled = undefined as boolean | undefined,
  withRuntimeTables = false,
  lazyMode = false,
} = {}) {
  doProving = proofsEnabled ?? doProving;

  if (doProving) {
    let methodsMeta = await analyzeMethods();
    let gates = methodKeys.map((k) => methodsMeta[k].gates);
    let proofs = methodKeys.map((k) => methodsMeta[k].proofs);
    maxProofsVerified = computeMaxProofsVerified(proofs.map((p) => p.length));

    let { provers, verify, verificationKey } = await compileProgram({
      publicInputType,
      publicOutputType,
      methodIntfs,
      methods: methodFunctions,
      gates,
      proofs,
      proofSystemTag: selfTag,
      cache,
      forceRecompile,
      overrideWrapDomain: config.overrideWrapDomain,
      numChunks: config.numChunks,
      state: programState,
      withRuntimeTables,
      lazyMode,
    });

    compileOutput = { provers, verify, maxProofsVerified };
    return { verificationKey };
  } else {
    return {
      verificationKey: VerificationKey.empty(),
    };
  }

function toRegularProver<K extends MethodKey>(key: K, i: number): RegularProver_<K> {
  return async function prove_(inputPublicInput, ...inputArgs) {
    let publicInput = publicInputType.fromValue(inputPublicInput);
    let args = zip(inputArgs, privateInputTypes[i]).map(([arg, type]) =>
      ProvableType.get(type).fromValue(arg)
    );
    if (!doProving) {
      // we step into a ZkProgramContext here to match the context nesting
      // that would happen if proofs were enabled -- otherwise, proofs declared
      // in an inner program could be counted to the outer program
      let id = ZkProgramContext.enter();
      try {
        let { publicOutput, auxiliaryOutput } =
          (hasPublicInput
            ? await (methods[key].method as any)(publicInput, ...args)
            : await (methods[key].method as any)(...args)) ?? {};

        let proof = await SelfProof.dummy(
          publicInput,
          publicOutput,
          await getMaxProofsVerified()
        );
        return { proof, auxiliaryOutput };
      } finally {
        ZkProgramContext.leave(id);
      }
    }

function verify(proof: Proof<PublicInput, PublicOutput>) {
  if (!doProving) {
    return Promise.resolve(true);
  }
  if (compileOutput?.verify === undefined) {
    throw Error(
      `Cannot verify proof, verification key not found. Try calling \`await program.compile()\` first.`
    );
  }
  let statement = MlPair(
    toFieldConsts(publicInputType, proof.publicInput),
    toFieldConsts(publicOutputType, proof.publicOutput)
  );
  return compileOutput.verify(statement, proof.proof);

proofsEnabled: doProving,
setProofsEnabled(proofsEnabled: boolean) {
  doProving = proofsEnabled;
},

const cacheHeaderVersion = 1;

type CommonHeader = {
  /**
   * Header version to avoid parsing incompatible headers.
   */
  version: number;
  /**
   * An identifier that is persistent even as versions of the data change. Safe to use as a file path.
   */
  persistentId: string;
  /**
   * A unique identifier for the data to be read. Safe to use as a file path.
   */
  uniqueId: string;
  /**
   * Specifies whether the data to be read is a utf8-encoded string or raw binary data. This was added
   * because node's `fs.readFileSync` returns garbage when reading string files without specifying the encoding.
   */
  dataType: 'string' | 'bytes';
};

type StepKeyHeader<Kind> = {
  kind: Kind;
  programName: string;
  methodName: string;
  methodIndex: number;
  hash: string;
};
type WrapKeyHeader<Kind> = { kind: Kind; programName: string; hash: string };
type PlainHeader<Kind> = { kind: Kind };

const LAGRANGE_BASIS_PREFIX = 'lagrange-basis' as const;

/**
 * A header that is passed to the caching layer, to support rich caching strategies.
 *
 * Both `uniqueId` and `programId` can safely be used as a file path.
 */
type CacheHeader = (
  | StepKeyHeader<'step-pk'>
  | StepKeyHeader<'step-vk'>
  | WrapKeyHeader<'wrap-pk'>
  | WrapKeyHeader<'wrap-vk'>
  | PlainHeader<'srs'>
  | PlainHeader<typeof LAGRANGE_BASIS_PREFIX>
) &
  CommonHeader;

function withVersion(
  header: Omit<CacheHeader, 'version'>,
  version = cacheHeaderVersion
): CacheHeader {
  let uniqueId = `${header.uniqueId}-${version}`;
  return { ...header, version, uniqueId } as CacheHeader;
}

function readCache<T>(
  cache: Cache,
  header: CacheHeader,
  transform?: (x: Uint8Array) => T
): T | undefined {
  try {
    let result = cache.read(header);
    if (result === undefined) {
      if (cache.debug) console.log(`cache miss: ${header.persistentId}`);
      return undefined;
    }
    if (transform === undefined) return result as any as T;
    return transform(result);
  } catch (e) {
    if (cache.debug) console.log('Failed to read cache', e);
    return undefined;
  }
}

function writeCache(cache: Cache, header: CacheHeader, value: Uint8Array) {
  if (!cache.canWrite) return false;
  try {
    cache.write(header, value);
    return true;
  } catch (e) {
    if (cache.debug) console.log('Failed to write cache', e);
    return false;

const FileSystem = (cacheDirectory: string, debug?: boolean): Cache => ({
  read({ persistentId, uniqueId, dataType }) {
    if (jsEnvironment !== 'node') throw Error('file system not available');

    let headerPath = resolve(cacheDirectory, `${persistentId}.header`);
    let dataPath = resolve(cacheDirectory, persistentId);

    // read current uniqueId, return data if it matches
    let currentId: string;
    try {
      currentId = readFileSync(headerPath, 'utf8');
    } catch (error) {
      if (isErr(error, 'ENOENT')) return undefined;
      throw error;
    }
    if (currentId !== uniqueId) return undefined;

    try {
      if (dataType === 'string') {
        let string = readFileSync(dataPath, 'utf8');
        return new TextEncoder().encode(string);
      } else {
        let buffer = readFileSync(dataPath);
        return new Uint8Array(buffer.buffer);
      }
    } catch (error) {
      if (isErr(error, 'ENOENT')) return undefined;
      throw error;
    }
  },
  write({ persistentId, uniqueId, dataType }, data) {
    if (jsEnvironment !== 'node') throw Error('file system not available');
    mkdirSync(cacheDirectory, { recursive: true });
    writeFileSync(resolve(cacheDirectory, `${persistentId}.header`), uniqueId, {
      encoding: 'utf8',
    });
    writeFileSync(resolve(cacheDirectory, persistentId), data, {
      encoding: dataType === 'string' ? 'utf8' : undefined,
    });

/**
 * Create `CacheHeader` from a `SnarkKeyHeader` plus some context available to `compile()`
 */
function parseHeader(
  programName: string,
  methods: MethodInterface[],
  header: SnarkKeyHeader
): CacheHeader {
  let hash = Pickles.util.fromMlString(header[1][2][6]);
  switch (header[0]) {
    case KeyType.StepProvingKey:
    case KeyType.StepVerificationKey: {
      let kind = snarkKeyStringKind[header[0]];
      let methodIndex = header[1][3];
      let methodName = methods[methodIndex].methodName;
      let persistentId = sanitize(`${kind}-${programName}-${methodName}`);
      let uniqueId = sanitize(
        `${kind}-${programName}-${methodIndex}-${methodName}-${hash}`
      );
      return {
        version: cacheHeaderVersion,
        uniqueId,
        kind,
        persistentId,
        programName,
        methodName,
        methodIndex,
        hash,
        dataType: snarkKeySerializationType[header[0]],
      };
    }
    case KeyType.WrapProvingKey:
    case KeyType.WrapVerificationKey: {
      let kind = snarkKeyStringKind[header[0]];
      let dataType = snarkKeySerializationType[header[0]];
      let persistentId = sanitize(`${kind}-${programName}`);
      let uniqueId = sanitize(`${kind}-${programName}-${hash}`);
      return {
        version: cacheHeaderVersion,
        uniqueId,
        kind,
        persistentId,
        programName,
        hash,
        dataType,
      };
    }

/**
 * Decode bytes to a snark key with the help of its header
 */
function decodeProverKey(header: SnarkKeyHeader, bytes: Uint8Array): SnarkKey {
  switch (header[0]) {
    case KeyType.StepProvingKey: {
      let index = wasm.caml_pasta_fp_plonk_index_decode(bytes, Pickles.loadSrsFp());
      let cs = header[1][4];
      return [KeyType.StepProvingKey, [0, index, cs]];
    }
    case KeyType.StepVerificationKey: {
      let srs = Pickles.loadSrsFp();
      let string = new TextDecoder().decode(bytes);
      let vkWasm = wasm.caml_pasta_fp_plonk_verifier_index_deserialize(srs, string);
      const rustConversion = getRustConversion(wasm);
      let vkMl = rustConversion.fp.verifierIndexFromRust(vkWasm);
      return [KeyType.StepVerificationKey, vkMl];
    }
    case KeyType.WrapProvingKey: {
      let index = wasm.caml_pasta_fq_plonk_index_decode(bytes, Pickles.loadSrsFq());
      let cs = header[1][3];
      return [KeyType.WrapProvingKey, [0, index, cs]];
    }
    case KeyType.WrapVerificationKey: {
      let string = new TextDecoder().decode(bytes);
      let vk = Pickles.decodeVerificationKey(string);
      return [KeyType.WrapVerificationKey, vk];
    }

let auxiliaryOutputExists = auxiliaryType && auxiliaryType.sizeInFields() !== 0;

let auxiliaryOutput;
if (auxiliaryOutputExists) {
  auxiliaryOutput = programState.getAuxiliaryOutput(methodIntfs[i].methodName);

  programState.reset(methodIntfs[i].methodName);
}

let [publicOutputFields, proof] = MlPair.from(result);

let nonPureOutput = programState.getNonPureOutput();

let publicOutput = fromFieldConsts(publicOutputType, publicOutputFields, nonPureOutput);

programState.reset('__nonPureOutput__');

return {
  proof: new SelfProof({
    publicInput,
    publicOutput,
    proof,
    maxProofsVerified,
  }),
  auxiliaryOutput,
};

// if the output is empty, we don't evaluate `toFields(result)` to allow the function to return something else in that case
let hasPublicOutput = publicOutputType.sizeInFields() !== 0;
let publicOutput = hasPublicOutput ? publicOutputType.toFields(result.publicOutput) : [];

if (state !== undefined && auxiliaryType !== undefined && auxiliaryType.sizeInFields() !== 0) {
  Provable.asProver(() => {
    let { auxiliaryOutput } = result;
    assert(
      auxiliaryOutput !== undefined,
      `${proofSystemTag.name}.${methodName}(): Auxiliary output is undefined even though the method declares it.`
    );
    state.setAuxiliaryOutput(Provable.toConstant(auxiliaryType, auxiliaryOutput), methodName);
  });
}

return {
  publicOutput: MlFieldArray.to(publicOutput),
  previousStatements: MlArray.to(previousStatements),
  previousProofs: MlArray.to(proofs.map((p) => p.proofInstance.proof)),
  shouldVerify: MlArray.to(
    proofs.map((proof) => proof.proofInstance.shouldVerify.toField().value)
  ),
};

toJSON(): JsonProof {
  let fields = this.publicFields();
  return {
    publicInput: fields.input.map(String),
    publicOutput: fields.output.map(String),
    maxProofsVerified: this.maxProofsVerified,
    proof: Pickles.proofToBase64([this.maxProofsVerified, this.proof]),
  };

addSideloadedProgram: {
  privateInputs: [VerificationKey, MerkleTreeWitness],
  async method(
    publicInput: MainProgramState,
    vk: VerificationKey,
    merkleWitness: MerkleTreeWitness
  ) {
    // In practice, this method would be guarded via some access control mechanism
    const currentRoot = merkleWitness.calculateRoot(Field(0));
    publicInput.treeRoot.assertEquals(
      currentRoot,
      'Provided merklewitness not correct or leaf not empty'
    );
    const newRoot = merkleWitness.calculateRoot(vk.hash);

    return {
      publicOutput: new MainProgramState({
        state: publicInput.state,
        treeRoot: newRoot,
      }),
    };
  },
},
validateUsingTree: {
  privateInputs: [SelfProof, VerificationKey, MerkleTreeWitness, SideloadedProgramProof],
  async method(
    publicInput: MainProgramState,
    previous: Proof<MainProgramState, MainProgramState>,
    vk: VerificationKey,
    merkleWitness: MerkleTreeWitness,
    proof: SideloadedProgramProof
  ) {
    // Verify previous program state
    previous.publicOutput.state.assertEquals(publicInput.state);
    previous.publicOutput.treeRoot.assertEquals(publicInput.treeRoot);

    // Verify inclusion of vk inside the tree
    const computedRoot = merkleWitness.calculateRoot(vk.hash);
    publicInput.treeRoot.assertEquals(
      computedRoot,
      'Tree witness with provided vk not correct'
    );

    proof.verify(vk);

    // Compute new state
    proof.publicInput.assertEquals(publicInput.state);
    const newState = proof.publicOutput;
    return {
      publicOutput: new MainProgramState({
        treeRoot: publicInput.treeRoot,
        state: newState,
      }),
    };
  },
